// SAAX Protocol — Day 15, Item 1: Evidence / Attestation Abstraction
//
// Provider-neutral, externally-generated, independently-verifiable evidence
// bound to acceptance criteria.
//
// CRITICAL PRINCIPLE: SAAX never produces evidence and never trusts the buyer
// or seller to declare fulfillment. Evidence is generated by EXTERNAL sources
// (temperature sensors, delivery trackers, reputation oracles, inspectors)
// with independent verification. SAAX validates structure, signature,
// provenance and binding, then evaluates the evidence against the commitment's
// acceptance-criterion verification policies.
//
// Evidence record (schema — every field validated, only recognized fields kept):
// {
//   "evidenceId": "0x...",                  // unique identifier
//   "evidenceType": "temperature-reading",  // domain-specific type
//   "issuer": "0x...",                      // who produced this evidence
//   "subject": "0x...",                     // what the evidence is about
//   "issuanceTimestamp": "2026-10-06T...",  // when the evidence was produced
//   "contextReference": "0x...",            // request/context reference
//   "payload": { ... },                     // the evidence content
//   "payloadHash": "sha256:...",            // hash of the payload
//   "provenance": { ... },                  // source chain, transport metadata
//   "signature": "COSE_Sign1...",           // cryptographic proof of integrity
//   "verificationScheme": "eip712|cose|jws",// which scheme verifies this
//   "verificationMaterial": "0x...",        // key, certificate, or reference
//   "commitmentId": "0x...",                // which commitment this binds to
//   "acceptanceCriterionId": "0x..."        // which criterion this satisfies
// }
//
// Verification policy (per acceptance criterion on the commitment):
// {
//   "criterionId": "0x...",
//   "criterionDescription": "delivery temperature <= 5C",
//   "requiredEvidenceType": "temperature-reading",
//   "acceptedIssuers": ["0x..."],            // optional allowlist
//   "verificationScheme": "cose",
//   "evaluationLogic": "payload.temperature <= 5",
//   "maxEvidenceAge": 3600,                  // seconds
//   "minimumEvidenceCount": 1
// }
//
// SIGNATURE NOTE (consistent with the commitment module's Phase-1 posture):
// COSE_Sign1 and JWS are EMULATED structurally (tagged envelope + signature
// hex); the one scheme this module verifies CRYPTOGRAPHICALLY is `eip712`
// (viem signTypedData/verifyTypedData over the EIP-712 domain
// { name:'SAAX Evidence', version:'1' }). For `cose`/`jws` the structural
// envelope + signature format is validated; real token verification for those
// schemes requires the pluggable verifier (see verifyEvidenceSignature) and is
// a later-phase wiring. This mirrors how the commitment manifest emulates
// COSE_Sign1 while real signing plugs in via hooks.

const crypto = require('crypto');
const { keccak256, toHex, getAddress, verifyTypedData } = require('viem');
const { signTypedData } = require('viem/accounts');
// Phase 5B: real COSE/JWS cryptographic verification (jose + cbor + node:crypto).
// Loaded lazily so the eip712-only code path has no extra dependency cost.
let _coseJwsVerifier = null;
function coseJwsVerifier() {
  if (!_coseJwsVerifier) {
    _coseJwsVerifier = require('./cose-jws-verifier.js');
  }
  return _coseJwsVerifier;
}

// ---- EIP-712 domain + primary type for evidence (eip712 scheme) ---------------
const EVIDENCE_TYPES = {
  Evidence: [
    { name: 'evidenceId', type: 'string' },
    { name: 'issuer', type: 'address' },
    { name: 'subject', type: 'address' },
    { name: 'commitmentId', type: 'string' },
    { name: 'acceptanceCriterionId', type: 'string' },
    { name: 'payloadHash', type: 'string' },
  ],
};
const EVIDENCE_DOMAIN_NAME = 'SAAX Evidence';
const EVIDENCE_DOMAIN_VERSION = '1';

// ---- Constants ---------------------------------------------------------------
const SCHEMES = ['eip712', 'cose', 'jws'];
const PAYLOAD_HASH_RE = /^sha256:[0-9a-f]{64}$/i;

// ---- Structural validation -----------------------------------------------------
// Returns { ok, reason }. Validates every REQUIRED field is present and of the
// right shape; `cose`/`jws` schemes require the signature format to match,
// `eip712` requires an EIP-712 signature recovery shape (0x + 130 hex).
function validateEvidenceStructure(evidence) {
  if (!evidence || typeof evidence !== 'object') return { ok: false, reason: 'evidence must be an object' };
  if (!evidence.evidenceId || typeof evidence.evidenceId !== 'string') return { ok: false, reason: 'evidenceId must be a string' };
  if (!evidence.evidenceType || typeof evidence.evidenceType !== 'string') return { ok: false, reason: 'evidenceType must be a string' };
  if (!evidence.issuer || !/^0x[a-fA-F0-9]{40}$/.test(evidence.issuer)) return { ok: false, reason: 'issuer must be an address' };
  if (!evidence.subject || !/^0x[a-fA-F0-9]{40}$/.test(evidence.subject)) return { ok: false, reason: 'subject must be an address' };
  if (!evidence.issuanceTimestamp || isNaN(Date.parse(evidence.issuanceTimestamp))) {
    return { ok: false, reason: 'issuanceTimestamp must be a parseable ISO 8601 timestamp' };
  }
  if (!evidence.payload || typeof evidence.payload !== 'object') return { ok: false, reason: 'payload must be an object' };
  if (!evidence.payloadHash || typeof evidence.payloadHash !== 'string' || !PAYLOAD_HASH_RE.test(evidence.payloadHash)) {
    return { ok: false, reason: 'payloadHash must be sha256:<64 hex>' };
  }
  if (!evidence.provenance || typeof evidence.provenance !== 'object') return { ok: false, reason: 'provenance must be an object' };
  if (!evidence.verificationScheme || !SCHEMES.includes(String(evidence.verificationScheme).toLowerCase())) {
    return { ok: false, reason: 'verificationScheme must be one of eip712|cose|jws' };
  }
  if (!evidence.signature || typeof evidence.signature !== 'string') return { ok: false, reason: 'signature is required' };
  const scheme = String(evidence.verificationScheme).toLowerCase();
  if (scheme === 'eip712' && !/^0x[a-fA-F0-9]{130}$/.test(evidence.signature)) {
    return { ok: false, reason: 'eip712 signature must be 65-byte hex (0x + 130 hex chars)' };
  }
  if ((scheme === 'cose' || scheme === 'jws') && !String(evidence.signature).startsWith(scheme.toUpperCase() + '_')) {
    return { ok: false, reason: scheme + ' signature must carry the ' + scheme.toUpperCase() + '_ envelope tag' };
  }
  if (evidence.commitmentId !== undefined && evidence.commitmentId !== null && typeof evidence.commitmentId !== 'string') {
    return { ok: false, reason: 'commitmentId must be a string when present' };
  }
  if (evidence.acceptanceCriterionId !== undefined && evidence.acceptanceCriterionId !== null && typeof evidence.acceptanceCriterionId !== 'string') {
    return { ok: false, reason: 'acceptanceCriterionId must be a string when present' };
  }
  return { ok: true, reason: null };
}

// ---- Payload hash --------------------------------------------------------------
// sha256 hex of the canonical JSON encoding of the payload (sorted keys,
// no whitespace). The issuer commits to the payload via this hash; any payload
// tampering changes the hash.
function hashPayload(payload) {
  const canonical = JSON.stringify(payload, (k, v) => {
    if (v && typeof v === 'object') {
      return Object.keys(v).sort().reduce((a, key) => { a[key] = v[key]; return a; }, {});
    }
    return v;
  });
  return 'sha256:' + crypto.createHash('sha256').update(canonical, 'utf8').digest('hex');
}

// ---- Signature verification (scheme-aware) --------------------------------------
// eip712: real EIP-712 recovery — verifyTypedData returns whether the signature
// recovers to the claimed issuer over the EIP-712 domain.
// cose/jws: structural envelope validation only (Phase 1 posture — the same
// emulation the commitment module uses). An optional verifyVerifier hook can be
// injected for real token verification in a later phase.
async function verifyEvidenceSignature(evidence, opts = {}) {
  const scheme = String(evidence.verificationScheme).toLowerCase();
  if (scheme === 'eip712') {
    try {
      const ok = await verifyTypedData({
        address: evidence.issuer,
        types: EVIDENCE_TYPES,
        primaryType: 'Evidence',
        message: {
          evidenceId: evidence.evidenceId,
          issuer: evidence.issuer,
          subject: evidence.subject,
          commitmentId: String(evidence.commitmentId || ''),
          acceptanceCriterionId: String(evidence.acceptanceCriterionId || ''),
          payloadHash: evidence.payloadHash,
        },
        domain: { name: EVIDENCE_DOMAIN_NAME, version: EVIDENCE_DOMAIN_VERSION },
        signature: evidence.signature,
      });
      return { ok: !!ok, reason: ok ? null : 'eip712 signature does not recover to the claimed issuer' };
    } catch (e) {
      return { ok: false, reason: 'eip712 verification failed: ' + String(e.message || e).slice(0, 160) };
    }
  }
  // cose / jws — structural envelope emulation. The signature string must carry
  // the envelope tag and non-trivial payload; the optional hook can do real
  // verification (later-phase wiring).
  const tag = scheme.toUpperCase() + '_';
  const sig = String(evidence.signature || '');
  if (!sig.startsWith(tag)) return { ok: false, reason: 'missing ' + tag + ' envelope tag' };
  if (sig.length <= tag.length + 1) return { ok: false, reason: scheme + ' envelope carries no signature material' };
  if (opts && typeof opts.verifyVerifier === 'function') {
    try {
      const r = await opts.verifyVerifier(evidence);
      return { ok: !!r, reason: r ? null : 'verifier hook rejected ' + scheme + ' evidence' };
    } catch (e) {
      return { ok: false, reason: 'verifier hook error: ' + String(e.message || e).slice(0, 160) };
    }
  }
  // Phase 5B: real cryptographic verification. NEVER ok:true on structure alone.
  try {
    const r = await coseJwsVerifier().verifyCoseJws(evidence, opts);
    return { ok: !!r.ok, reason: r.ok ? null : (r.reason || scheme + ' verification failed') };
  } catch (e) {
    return { ok: false, reason: scheme + ' verification error: ' + String(e.message || e).slice(0, 160) };
  }
}

// ---- Provenance validation -------------------------------------------------------
// provenance must carry a source identification record; when kind=chain the
// sourceTx is required. Returns { ok, reason }.
function validateProvenance(provenance) {
  if (!provenance || typeof provenance !== 'object') return { ok: false, reason: 'provenance is required' };
  if (!provenance.source || typeof provenance.source !== 'string') return { ok: false, reason: 'provenance.source is required' };
  if (provenance.kind === 'chain' && (!provenance.sourceTx || typeof provenance.sourceTx !== 'string')) {
    return { ok: false, reason: 'provenance.kind=chain requires sourceTx' };
  }
  return { ok: true, reason: null };
}

// ---- Policy model ---------------------------------------------------------------
// Verification policy per acceptance criterion. Validates shape; returns
// { ok, reason }.
function validateVerificationPolicy(policy) {
  if (!policy || typeof policy !== 'object') return { ok: false, reason: 'policy must be an object' };
  if (!policy.criterionId || typeof policy.criterionId !== 'string') return { ok: false, reason: 'criterionId is required' };
  if (!policy.requiredEvidenceType || typeof policy.requiredEvidenceType !== 'string') return { ok: false, reason: 'requiredEvidenceType is required' };
  if (policy.acceptedIssuers !== undefined && policy.acceptedIssuers !== null) {
    if (!Array.isArray(policy.acceptedIssuers)) return { ok: false, reason: 'acceptedIssuers must be an array when present' };
    for (const a of policy.acceptedIssuers) {
      if (!/^0x[a-fA-F0-9]{40}$/.test(String(a))) return { ok: false, reason: 'acceptedIssuers entries must be addresses' };
    }
  }
  if (policy.verificationScheme !== undefined && policy.verificationScheme !== null &&
      !SCHEMES.includes(String(policy.verificationScheme).toLowerCase())) {
    return { ok: false, reason: 'verificationScheme must be one of eip712|cose|jws' };
  }
  if (policy.evaluationLogic !== undefined && policy.evaluationLogic !== null && typeof policy.evaluationLogic !== 'string') {
    return { ok: false, reason: 'evaluationLogic must be a string when present' };
  }
  if (policy.maxEvidenceAge !== undefined && policy.maxEvidenceAge !== null &&
      (!Number.isInteger(Number(policy.maxEvidenceAge)) || Number(policy.maxEvidenceAge) < 0)) {
    return { ok: false, reason: 'maxEvidenceAge must be a non-negative integer (seconds) when present' };
  }
  if (policy.minimumEvidenceCount !== undefined && policy.minimumEvidenceCount !== null &&
      (!Number.isInteger(Number(policy.minimumEvidenceCount)) || Number(policy.minimumEvidenceCount) < 1)) {
    return { ok: false, reason: 'minimumEvidenceCount must be a positive integer when present' };
  }
  return { ok: true, reason: null };
}

// ---- Evaluation-logic executor -----------------------------------------------------
// Evaluate a verification policy against the evidence evidence[]. The policy's
// evaluationLogic is a dsl string of form "<lhs> <op> <rhs>" where <lhs> is a
// dotted payload path (e.g. payload.temperature) and <rhs> is a numeric literal.
// This is a tiny SAFE evaluator — it does NOT eval() — only numeric comparison
// with a fixed operator set. Returns boolean.
function evaluateLogic(logicStr, payload) {
  if (!logicStr || typeof logicStr !== 'string') return true; // no logic -> satisfied by presence
  const parts = logicStr.split(/\s+/);
  if (parts.length < 3) return true; // malformed logic -> conservative pass on presence (caller may enforce scheme/issuer/age)
  const lhs = parts[0];
  const op = parts[1];
  const rhs = parts.slice(2).join(' '); // allow numeric suffix
  const num = /^[-+]?(\d+\.?\d*|\.\d+)$/;
  if (!num.test(rhs)) return true;
  // The payload PATH may be written with or without the `payload.` prefix
  // (e.g. 'payload.temperature' === 'temperature'). Strip a leading 'payload'
  // segment so the walk starts from the payload object itself.
  const path = lhs.split('.').filter(seg => seg !== '');
  if (path[0] === 'payload') path.shift();
  let cur = payload;
  for (const seg of path) {
    if (!cur || typeof cur !== 'object' || cur[seg] === undefined) return false;
    cur = cur[seg];
  }
  if (typeof cur === 'number') {
    const expected = Number(rhs);
    switch (op) {
      case '<=': return cur <= expected;
      case '>=': return cur >= expected;
      case '<': return cur < expected;
      case '>': return cur > expected;
      case '==': return cur === expected;
      case '!=': return cur !== expected;
      default: return true;
    }
  }
  if (typeof cur === 'string') {
    switch (op) {
      case '==': return cur === rhs.replace(/^["']|["']$/g, '');
      case '!=': return cur !== rhs.replace(/^["']|["']$/g, '');
      default: return true;
    }
  }
  return true;
}

// ---- Core: validateEvidence ---------------------------------------------------------
// Checks structure, signature, provenance, and binding to the commitment and
// criterion. Returns { ok, reason }. This is the FIRST gate: malformed or
// unverified evidence never reaches evaluation.
async function validateEvidence(evidence, commitment, opts = {}) {
  const structural = validateEvidenceStructure(evidence);
  if (!structural.ok) return { ok: false, reason: structural.reason, stage: 'structure' };
  // Binding to commitment
  if (!commitment || !commitment.commitmentId) return { ok: false, reason: 'commitment is required', stage: 'binding' };
  if (evidence.commitmentId && String(evidence.commitmentId) !== String(commitment.commitmentId)) {
    return { ok: false, reason: 'evidence.commitmentId does not bind to the commitment', stage: 'binding' };
  }
  // Signature verification (scheme-aware)
  const sig = await verifyEvidenceSignature(evidence, opts);
  if (!sig.ok) return { ok: false, reason: sig.reason, stage: 'signature' };
  // Provenance
  const prov = validateProvenance(evidence.provenance);
  if (!prov.ok) return { ok: false, reason: prov.reason, stage: 'provenance' };
  // Payload tampering check: recompute the hash and compare
  const recomputed = hashPayload(evidence.payload);
  if (String(recomputed).toLowerCase() !== String(evidence.payloadHash).toLowerCase()) {
    return { ok: false, reason: 'payload hash mismatch (tampering detected)', stage: 'payload-hash' };
  }
  return { ok: true, reason: null, stage: 'ok' };
}

// ---- Core: evaluateCriterion -----------------------------------------------------------
// Applies the verification policy to evidence[]. Returns one of:
//   satisfied | not_satisfied | insufficient_evidence
async function evaluateCriterion(criterion, evidenceList, opts = {}) {
  const policy = criterion && criterion.verificationPolicy ? criterion.verificationPolicy : criterion;
  const policyValid = validateVerificationPolicy(policy);
  if (!policyValid.ok) return { outcome: 'insufficient_evidence', reason: 'invalid policy: ' + policyValid.reason };

  const list = Array.isArray(evidenceList) ? evidenceList : [];
  const scheme = (policy.verificationScheme || 'eip712').toLowerCase();

  // Bind the evidence to the criterion: any evidence whose acceptanceCriterionId
  // is present and differs from the criterion's id is not eligible for THIS
  // criterion. Evidence without a criterion binding is eligible (it carries no
  // claim about which criterion it satisfies until bound).
  const bound = list.filter(ev =>
    !ev.acceptanceCriterionId ||
    String(ev.acceptanceCriterionId) === String(policy.criterionId));

  // Minimum evidence count
  const minCount = Number(policy.minimumEvidenceCount || 1);
  if (bound.length < minCount) {
    return { outcome: 'insufficient_evidence', reason: 'minimumEvidenceCount=' + minCount + ' unmet (have ' + bound.length + ')' };
  }

  // Validate each bound evidence structurally + signature + provenance + hash
  let valid = 0;
  let failedStage = null;
  let firstFailReason = null;
  for (const ev of bound) {
    const v = opts.skipValidation ? { ok: true } : await validateEvidence(ev, { commitmentId: ev.commitmentId }, opts);
    if (!v.ok) { failedStage = v.stage; firstFailReason = v.reason; continue; }
    valid++;
  }
  if (valid < minCount) {
    return { outcome: 'insufficient_evidence', reason: (failedStage ? 'invalid evidence (' + failedStage + '): ' + firstFailReason : 'minimumEvidenceCount unmet by valid evidence') };
  }

  // Evidence-type match
  for (const ev of bound) {
    if (String(ev.evidenceType) !== String(policy.requiredEvidenceType)) {
      return { outcome: 'not_satisfied', reason: 'wrong evidenceType: ' + ev.evidenceType + ' != ' + policy.requiredEvidenceType };
    }
  }

  // Issuer allowlist (optional)
  if (policy.acceptedIssuers && policy.acceptedIssuers.length) {
    const allowed = policy.acceptedIssuers.map(a => String(a).toLowerCase());
    for (const ev of bound) {
      if (!allowed.includes(String(ev.issuer).toLowerCase())) {
        return { outcome: 'not_satisfied', reason: 'issuer not in acceptedIssuers allowlist: ' + ev.issuer };
      }
    }
  }

  // Freshness (optional maxEvidenceAge)
  if (policy.maxEvidenceAge !== undefined && policy.maxEvidenceAge !== null) {
    const maxAge = Number(policy.maxEvidenceAge);
    const nowMs = Date.now();
    for (const ev of bound) {
      const issuedMs = Date.parse(ev.issuanceTimestamp);
      if (isNaN(issuedMs)) return { outcome: 'not_satisfied', reason: 'evidence issuanceTimestamp unparseable' };
      if (nowMs - issuedMs > maxAge * 1000) {
        return { outcome: 'not_satisfied', reason: 'evidence older than maxEvidenceAge (' + maxAge + 's)' };
      }
    }
  }

  // Evaluation logic
  if (policy.evaluationLogic) {
    let anyTrue = false;
    for (const ev of bound) {
      if (evaluateLogic(policy.evaluationLogic, ev.payload)) { anyTrue = true; break; }
    }
    if (!anyTrue) {
      return { outcome: 'not_satisfied', reason: 'evaluationLogic not met: ' + policy.evaluationLogic };
    }
  }

  return { outcome: 'satisfied', reason: null, evidenceUsed: bound.length };
}

// ---- Core: recordOutcome ---------------------------------------------------------------
// Writes the evaluation result to the commitment record. The commitment record
// (object) gains an evidenceOutcomes map keyed by criterionId. Returns the
// updated commitment record. When a store adapter is supplied, also persists.
function recordOutcome(commitmentId, criterionId, outcome, evidenceRefs, opts = {}) {
  if (!commitmentId || typeof commitmentId !== 'string') throw new Error('recordOutcome: commitmentId is required');
  if (!criterionId || typeof criterionId !== 'string') throw new Error('recordOutcome: criterionId is required');
  if (!['satisfied', 'not_satisfied', 'insufficient_evidence'].includes(String(outcome))) {
    throw new Error('recordOutcome: outcome must be one of satisfied|not_satisfied|insufficient_evidence');
  }
  const refs = Array.isArray(evidenceRefs) ? evidenceRefs.map(r => String(r)) : (evidenceRefs ? [String(evidenceRefs)] : []);
  const rec = {
    criterionId,
    outcome: String(outcome),
    evidenceRefs: refs,
    recordedAt: new Date().toISOString(),
  };
  const commitment = (opts && opts.commitment) ? opts.commitment : null;
  if (commitment && typeof commitment === 'object') {
    if (!commitment.evidenceOutcomes) commitment.evidenceOutcomes = {};
    commitment.evidenceOutcomes[criterionId] = rec;
  }
  if (opts && typeof opts.store === 'function') {
    opts.store({ commitmentId, criterionId, record: rec });
  }
  return commitment ? commitment : rec;
}

// ---- In-process outcome store (Phase 1, mirrors requirement.js) --------------------
const _outcomeStore = new Map(); // commitmentId -> { criterionId -> record }
function persistOutcome(commitmentId, criterionId, record) {
  if (!_outcomeStore.has(commitmentId)) _outcomeStore.set(commitmentId, {});
  _outcomeStore.get(commitmentId)[criterionId] = record;
}
function getOutcome(commitmentId, criterionId) {
  const recs = _outcomeStore.get(commitmentId);
  return recs ? (recs[criterionId] || null) : null;
}
function listOutcomes(commitmentId) {
  return _outcomeStore.get(commitmentId) ? { ..._outcomeStore.get(commitmentId) } : {};
}
function reset() {
  _outcomeStore.clear();
}
// Convenience: recordOutcome with the in-process store as the default adapter.
function recordOutcomeInStore(commitmentId, criterionId, outcome, evidenceRefs) {
  const record = recordOutcome(commitmentId, criterionId, outcome, evidenceRefs, {
    store: persistOutcome,
  });
  return record;
}

module.exports = {
  // structure + policies
  validateEvidenceStructure,
  validateVerificationPolicy,
  validateProvenance,
  hashPayload,
  verifyEvidenceSignature,
  evaluateLogic,
  // core
  validateEvidence,
  evaluateCriterion,
  recordOutcome,
  // store
  persistOutcome,
  getOutcome,
  listOutcomes,
  resolveOutcome: getOutcome, // alias
  reset,
  // constants
  EVIDENCE_TYPES,
  EVIDENCE_DOMAIN_NAME,
  EVIDENCE_DOMAIN_VERSION,
  SCHEMES,
  PAYLOAD_HASH_RE,
};